/**
 * Outcome of a beam.
 *
 * Non-throwing on purpose: the App Intent always has to render *something* to Shortcuts,
 * and a thrown error there degrades into a generic system failure message.
 */

public enum BeamResult: Equatable, Hashable {
    
    case sent(clipId: String
    )
    case notPaired
    case unreachable
    case timedOut
    case tooLarge(maxBytes: UInt32
    )
    case failed(reason: String
    )





}

#if compiler(>=6)
extension BeamResult: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBeamResult: FfiConverterRustBuffer {
    typealias SwiftType = BeamResult

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BeamResult {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .sent(clipId: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .notPaired
        
        case 3: return .unreachable
        
        case 4: return .timedOut
        
        case 5: return .tooLarge(maxBytes: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 6: return .failed(reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BeamResult, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .sent(clipId):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(clipId, into: &buf)
            
        
        case .notPaired:
            writeInt(&buf, Int32(2))
        
        
        case .unreachable:
            writeInt(&buf, Int32(3))
        
        
        case .timedOut:
            writeInt(&buf, Int32(4))
        
        
        case let .tooLarge(maxBytes):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(maxBytes, into: &buf)
            
        
        case let .failed(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


